--
-- Name: analytics_dimension_users; Type: VIEW; Schema: source_govocal_com; Owner: -
--

CREATE VIEW source_govocal_com.analytics_dimension_users AS
 SELECT u.id,
    COALESCE(((u.roles -> 0) ->> 'type'::text), 'citizen'::text) AS role,
    u.invite_status,
    (users_with_visits.dimension_user_id IS NOT NULL) AS has_visits
   FROM (source_govocal_com.users u
     LEFT JOIN ( SELECT DISTINCT analytics_fact_visits.dimension_user_id
           FROM source_govocal_com.analytics_fact_visits) users_with_visits ON ((users_with_visits.dimension_user_id = u.id)));


