--
-- Name: analytics_fact_participations; Type: VIEW; Schema: source_govocal_com; Owner: -
--

CREATE VIEW source_govocal_com.analytics_fact_participations AS
 SELECT i.id,
    i.author_id AS dimension_user_id,
    COALESCE((i.author_id)::text, (i.author_hash)::text, (i.id)::text) AS participant_id,
    i.project_id AS dimension_project_id,
        CASE
            WHEN ((ph.participation_method)::text = 'native_survey'::text) THEN survey.id
            ELSE idea.id
        END AS dimension_type_id,
    (i.created_at)::date AS dimension_date_created_id,
    (i.likes_count + i.dislikes_count) AS reactions_count,
    i.likes_count,
    i.dislikes_count
   FROM ((((source_govocal_com.ideas i
     LEFT JOIN source_govocal_com.projects pr ON ((pr.id = i.project_id)))
     LEFT JOIN source_govocal_com.phases ph ON ((ph.id = i.creation_phase_id)))
     JOIN source_govocal_com.analytics_dimension_types idea ON (((idea.name)::text = 'idea'::text)))
     LEFT JOIN source_govocal_com.analytics_dimension_types survey ON (((survey.name)::text = 'survey'::text)))
  WHERE ((i.publication_status)::text = 'published'::text)
UNION ALL
 SELECT c.id,
    c.author_id AS dimension_user_id,
    COALESCE((c.author_id)::text, (c.author_hash)::text, (c.id)::text) AS participant_id,
    i.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (c.created_at)::date AS dimension_date_created_id,
    (c.likes_count + c.dislikes_count) AS reactions_count,
    c.likes_count,
    c.dislikes_count
   FROM ((source_govocal_com.comments c
     JOIN source_govocal_com.analytics_dimension_types adt ON ((((adt.name)::text = 'comment'::text) AND ((adt.parent)::text = 'idea'::text))))
     LEFT JOIN source_govocal_com.ideas i ON ((c.idea_id = i.id)))
UNION ALL
 SELECT r.id,
    r.user_id AS dimension_user_id,
    COALESCE((r.user_id)::text, (r.id)::text) AS participant_id,
    COALESCE(i.project_id, ic.project_id) AS dimension_project_id,
    adt.id AS dimension_type_id,
    (r.created_at)::date AS dimension_date_created_id,
    1 AS reactions_count,
        CASE
            WHEN ((r.mode)::text = 'up'::text) THEN 1
            ELSE 0
        END AS likes_count,
        CASE
            WHEN ((r.mode)::text = 'down'::text) THEN 1
            ELSE 0
        END AS dislikes_count
   FROM ((((source_govocal_com.reactions r
     JOIN source_govocal_com.analytics_dimension_types adt ON ((((adt.name)::text = 'reaction'::text) AND ((adt.parent)::text = lower((r.reactable_type)::text)))))
     LEFT JOIN source_govocal_com.ideas i ON ((i.id = r.reactable_id)))
     LEFT JOIN source_govocal_com.comments c ON ((c.id = r.reactable_id)))
     LEFT JOIN source_govocal_com.ideas ic ON ((ic.id = c.idea_id)))
UNION ALL
 SELECT pr.id,
    pr.user_id AS dimension_user_id,
    COALESCE((pr.user_id)::text, (pr.id)::text) AS participant_id,
    p.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (pr.created_at)::date AS dimension_date_created_id,
    0 AS reactions_count,
    0 AS likes_count,
    0 AS dislikes_count
   FROM ((source_govocal_com.polls_responses pr
     LEFT JOIN source_govocal_com.phases p ON ((p.id = pr.phase_id)))
     JOIN source_govocal_com.analytics_dimension_types adt ON (((adt.name)::text = 'poll'::text)))
UNION ALL
 SELECT vv.id,
    vv.user_id AS dimension_user_id,
    COALESCE((vv.user_id)::text, (vv.id)::text) AS participant_id,
    p.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (vv.created_at)::date AS dimension_date_created_id,
    0 AS reactions_count,
    0 AS likes_count,
    0 AS dislikes_count
   FROM (((source_govocal_com.volunteering_volunteers vv
     LEFT JOIN source_govocal_com.volunteering_causes vc ON ((vc.id = vv.cause_id)))
     LEFT JOIN source_govocal_com.phases p ON ((p.id = vc.phase_id)))
     JOIN source_govocal_com.analytics_dimension_types adt ON (((adt.name)::text = 'volunteer'::text)))
UNION ALL
 SELECT b.id,
    b.user_id AS dimension_user_id,
    COALESCE((b.user_id)::text, (b.id)::text) AS participant_id,
    p.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (b.created_at)::date AS dimension_date_created_id,
    0 AS reactions_count,
    0 AS likes_count,
    0 AS dislikes_count
   FROM ((source_govocal_com.baskets b
     LEFT JOIN source_govocal_com.phases p ON ((p.id = b.phase_id)))
     JOIN source_govocal_com.analytics_dimension_types adt ON (((adt.name)::text = 'basket'::text)))
UNION ALL
 SELECT ea.id,
    ea.attendee_id AS dimension_user_id,
    (ea.attendee_id)::text AS participant_id,
    e.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (ea.created_at)::date AS dimension_date_created_id,
    0 AS reactions_count,
    0 AS likes_count,
    0 AS dislikes_count
   FROM ((source_govocal_com.events_attendances ea
     LEFT JOIN source_govocal_com.events e ON ((e.id = ea.event_id)))
     JOIN source_govocal_com.analytics_dimension_types adt ON (((adt.name)::text = 'event_attendance'::text)));


--
-- Name: analytics_fact_posts; Type: VIEW; Schema: source_govocal_com; Owner: -
--

CREATE VIEW source_govocal_com.analytics_fact_posts AS
 SELECT i.id,
    i.author_id AS user_id,
    i.project_id AS dimension_project_id,
    adt.id AS dimension_type_id,
    (i.created_at)::date AS dimension_date_created_id,
    (abf.feedback_first_date)::date AS dimension_date_first_feedback_id,
    i.idea_status_id AS dimension_status_id,
    (abf.feedback_first_date - i.created_at) AS feedback_time_taken,
    COALESCE(abf.feedback_official, 0) AS feedback_official,
    COALESCE(abf.feedback_status_change, 0) AS feedback_status_change,
        CASE
            WHEN (abf.feedback_first_date IS NULL) THEN 1
            ELSE 0
        END AS feedback_none,
    (i.likes_count + i.dislikes_count) AS reactions_count,
    i.likes_count,
    i.dislikes_count,
    i.publication_status
   FROM (((source_govocal_com.ideas i
     LEFT JOIN source_govocal_com.analytics_build_feedbacks abf ON ((abf.post_id = i.id)))
     LEFT JOIN source_govocal_com.phases creation_phase ON ((i.creation_phase_id = creation_phase.id)))
     JOIN source_govocal_com.analytics_dimension_types adt ON (((adt.name)::text =
        CASE
            WHEN (creation_phase.* IS NULL) THEN 'idea'::text
            WHEN ((creation_phase.participation_method)::text = 'proposals'::text) THEN 'proposal'::text
            ELSE NULL::text
        END)))
  WHERE ((creation_phase.* IS NULL) OR ((creation_phase.participation_method)::text = 'proposals'::text));


--
-- Name: analytics_fact_project_statuses; Type: VIEW; Schema: source_govocal_com; Owner: -
--

CREATE VIEW source_govocal_com.analytics_fact_project_statuses AS
 WITH finished_statuses_for_timeline_projects AS (
         SELECT phases.project_id,
            ((max(phases.end_at) + 1))::timestamp without time zone AS "timestamp"
           FROM source_govocal_com.phases
          GROUP BY phases.project_id
         HAVING (max(phases.end_at) < now())
        )
 SELECT ap.publication_id AS dimension_project_id,
    ap.publication_status AS status,
    (((ap.publication_status)::text = 'archived'::text) OR ((fsftp.project_id IS NOT NULL) AND ((ap.publication_status)::text <> 'draft'::text))) AS finished,
    COALESCE(fsftp."timestamp", ap.updated_at) AS "timestamp",
    COALESCE((fsftp."timestamp")::date, (ap.updated_at)::date) AS dimension_date_id
   FROM ((source_govocal_com.admin_publications ap
     LEFT JOIN source_govocal_com.projects p ON ((ap.publication_id = p.id)))
     LEFT JOIN finished_statuses_for_timeline_projects fsftp ON ((fsftp.project_id = ap.publication_id)))
  WHERE ((ap.publication_type)::text = 'Project'::text);


