--
-- Name: moderation_moderations; Type: VIEW; Schema: source_govocal_com; Owner: -
--

CREATE VIEW source_govocal_com.moderation_moderations AS
 SELECT ideas.id,
    'Idea'::text AS moderatable_type,
    NULL::text AS post_type,
    NULL::uuid AS post_id,
    NULL::character varying AS post_slug,
    NULL::jsonb AS post_title_multiloc,
    projects.id AS project_id,
    projects.slug AS project_slug,
    projects.title_multiloc AS project_title_multiloc,
    ideas.title_multiloc AS content_title_multiloc,
    ideas.body_multiloc AS content_body_multiloc,
    ideas.slug AS content_slug,
    ideas.published_at AS created_at,
    moderation_moderation_statuses.status AS moderation_status
   FROM ((source_govocal_com.ideas
     LEFT JOIN source_govocal_com.moderation_moderation_statuses ON ((moderation_moderation_statuses.moderatable_id = ideas.id)))
     LEFT JOIN source_govocal_com.projects ON ((projects.id = ideas.project_id)))
UNION ALL
 SELECT comments.id,
    'Comment'::text AS moderatable_type,
    'Idea'::text AS post_type,
    ideas.id AS post_id,
    ideas.slug AS post_slug,
    ideas.title_multiloc AS post_title_multiloc,
    projects.id AS project_id,
    projects.slug AS project_slug,
    projects.title_multiloc AS project_title_multiloc,
    NULL::jsonb AS content_title_multiloc,
    comments.body_multiloc AS content_body_multiloc,
    NULL::character varying AS content_slug,
    comments.created_at,
    moderation_moderation_statuses.status AS moderation_status
   FROM (((source_govocal_com.comments
     LEFT JOIN source_govocal_com.moderation_moderation_statuses ON ((moderation_moderation_statuses.moderatable_id = comments.id)))
     LEFT JOIN source_govocal_com.ideas ON ((ideas.id = comments.idea_id)))
     LEFT JOIN source_govocal_com.projects ON ((projects.id = ideas.project_id)));


